-- 队列基础：队尾入队、队头出队的 FIFO 语义。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '队列的 FIFO 语义与基本操作','队列在队尾插入、队头删除，先入队的元素先出队。',course.id,parent.id,'cs408-queue-fifo','AISTU',1,'REVIEWED',8,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-queue-fifo' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-queue-fifo',1,'REVIEWED','队列的 FIFO 语义与基本操作',JSON_OBJECT('summary','队列只允许在队尾 enqueue、在队头 dequeue，因此先进入的元素先离开。front 读取队头但不删除，判空和长度操作维护结构状态；空队列出队必须按接口规则处理下溢。','steps',JSON_ARRAY('队尾是唯一允许插入的一端','队头是唯一允许删除的一端','enqueue 把新元素加入队尾','dequeue 删除并返回队头元素','空队列出队必须处理下溢'),'prerequisite',JSON_OBJECT('contentKey','cs408-linear-list-definition-operations','title','线性表的定义与基本操作','description','先理解队列是限制插入和删除位置的线性表。'),'nextStep',JSON_OBJECT('contentKey','cs408-circular-queue-representation','title','循环队列的数组表示','description','继续学习如何用模运算复用数组槽位。')),JSON_OBJECT('id','queue-fifo-v1','prompt','队列的插入和删除分别发生在哪一端？','options',JSON_ARRAY(JSON_OBJECT('id','FIFO_ENDS','text','队尾插入、队头删除'),JSON_OBJECT('id','SAME_END','text','都在队头执行')),'correctOptionId','FIFO_ENDS','correctExplanation','正确：分离插入端与删除端才能保持先进先出的顺序。','incorrectExplanation','不正确：同一端插入和删除会形成栈式访问，不是队列的 FIFO 语义。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-queue-fifo' AND existing.content_version=1 WHERE point.content_key='cs408-queue-fifo' AND existing.id IS NULL;
